tape( 'the function accurately computes `2**x` for very small `x`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	x = tiny.x;
	expected = tiny.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = exp2f( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValue( y, e, 3 ), true, 'x: '+x[i]+'. y: '+y+'. E: '+e+'.' );
	}
	t.end();
});

tape( 'the function returns `+infinity` for very large `x`', opts, function test( t ) {
	t.strictEqual( exp2f( 1100.0 ), PINF, 'equals +infinity' );
	t.strictEqual( exp2f( 1200.0 ), PINF, 'equals +infinity' );
	t.strictEqual( exp2f( 1300.0 ), PINF, 'equals +infinity' );
	t.end();
});

tape( 'the function returns `0.0` for negative large `x`', opts, function test( t ) {
	t.strictEqual( exp2f( -1100.0 ), 0.0, 'equals 0' );
	t.strictEqual( exp2f( -1200.0 ), 0.0, 'equals 0' );
	t.strictEqual( exp2f( -1300.0 ), 0.0, 'equals 0' );
	t.end();
});

tape( 'the function returns `0.0` if provided `-infinity`', opts, function test( t ) {
	var val = exp2f( NINF );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', opts, function test( t ) {
	t.strictEqual( exp2f( PINF ), PINF, 'equals +infinity' );
	t.end();
});

tape( 'the function returns `1` if provided `+-0`', opts, function test( t ) {
	var v;

	v = exp2f( -0.0 );
	t.strictEqual( v, 1.0, 'returns expected value' );

	v = exp2f( +0.0 );
	t.strictEqual( v, 1.0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var val = exp2f( NaN );
	t.strictEqual( isnanf( val ), true, 'equals NaN' );
	t.end();
});
